(() => {
  const artwork = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 180 248\" role=\"img\" aria-label=\"Figurine with swept hair, a light shirt and dark pants\">\n  <defs>\n    <radialGradient id=\"sidekick-face\" cx=\"34%\" cy=\"25%\" r=\"78%\">\n      <stop stop-color=\"#fff\"/><stop offset=\".58\" stop-color=\"#fafafa\"/><stop offset=\".9\" stop-color=\"#e2e2e2\"/><stop offset=\"1\" stop-color=\"#d1d1d1\"/>\n    </radialGradient>\n    <linearGradient id=\"sidekick-hair\" x1=\"18%\" y1=\"5%\" x2=\"88%\" y2=\"100%\"><stop stop-color=\"#3b3b42\"/><stop offset=\".58\" stop-color=\"#202026\"/><stop offset=\"1\" stop-color=\"#111116\"/></linearGradient>\n    <radialGradient id=\"sidekick-body\" cx=\"32%\" cy=\"25%\" r=\"80%\">\n      <stop stop-color=\"#fff\"/><stop offset=\".48\" stop-color=\"#f9f9f9\"/><stop offset=\".87\" stop-color=\"#dedede\"/><stop offset=\"1\" stop-color=\"#c9c9c9\"/>\n    </radialGradient>\n    <linearGradient id=\"sidekick-limb\" x1=\"0\" x2=\"100%\">\n      <stop stop-color=\"#e6e6e6\"/><stop offset=\".36\" stop-color=\"#fff\"/><stop offset=\".68\" stop-color=\"#efefef\"/><stop offset=\"1\" stop-color=\"#c9c9c9\"/>\n    </linearGradient>\n    <radialGradient id=\"sidekick-shadow\">\n      <stop stop-color=\"#3a3a37\" stop-opacity=\".22\"/><stop offset=\"1\" stop-color=\"#3a3a37\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <ellipse cx=\"90\" cy=\"234\" rx=\"43\" ry=\"8\" fill=\"url(#sidekick-shadow)\"/>\n  <g stroke=\"#bcbcbc\" stroke-width=\".65\">\n    <g data-part=\"leg-left\">\n      <path fill=\"#5e6771\" d=\"M75 173 C76 165 88 165 89 175 C89 184 86 198 85 209 L85 222 C85 228 82 232 76 232 L68 232 C62 232 60 228 63 224 Q65 221 73 220 L73 202 Z\"/>\n    </g>\n    <g data-part=\"leg-right\">\n      <path fill=\"#5e6771\" d=\"M91 175 C92 165 104 165 105 173 L107 202 L107 220 Q115 221 117 224 C120 228 118 232 112 232 L104 232 C98 232 95 228 95 222 L95 209 C94 198 91 184 91 175Z\"/>\n    </g>\n    <g data-part=\"upper\">\n      <g data-part=\"arm-left\">\n        <path fill=\"url(#sidekick-limb)\" d=\"M75 127 C67 127 64 137 62 150 L58 171 C57 178 58 182 63 182 C67 182 69 178 69 172 L74 154 C78 144 83 130 75 127Z\"/>\n      </g>\n      <g data-part=\"arm-right\">\n        <path fill=\"url(#sidekick-limb)\" d=\"M105 127 C113 127 116 137 118 150 L122 171 C123 178 122 182 117 182 C113 182 111 178 111 172 L106 154 C102 144 97 130 105 127Z\"/>\n      </g>\n      <path fill=\"url(#sidekick-body)\" d=\"M82 115 H98 V129 H82Z\"/>\n      <path fill=\"#ebeae5\" d=\"M81 124 Q90 131 99 124 Q114 127 116 144 L108 147 L108 176 Q90 180 72 176 L72 147 L64 144 Q67 129 81 124Z\"/>\n      <path fill=\"none\" stroke=\"#353533\" stroke-width=\"2\" d=\"M81 124 Q90 134 99 124\"/>\n      <g data-part=\"head\" transform=\"translate(22 13) scale(.132)\">\n        <g fill=\"url(#sidekick-face)\" stroke=\"#bbb\" stroke-width=\"6\">\n          <path d=\"M268 554 C229 510 198 514 183 546 C160 593 192 608 275 612Z\"/>\n          <path d=\"M769 552 C803 506 823 513 832 550 C845 596 814 616 766 611Z\"/>\n          <path d=\"M269 359 C297 250 689 236 769 366 C780 476 776 645 750 718 C727 784 665 814 548 818 C445 822 345 799 300 753 C266 720 260 643 261 545Z\"/>\n        </g>\n        <path fill=\"url(#sidekick-hair)\" stroke=\"#232328\" stroke-width=\"6\" stroke-linejoin=\"round\" d=\"M262 539 C240 489 172 416 166 337 C157 247 189 183 248 144 C303 105 341 125 389 144 C387 111 407 90 437 76 C479 56 544 59 590 52 C659 44 704 22 732 9 C751 1 761 11 751 27 C739 45 699 63 663 79 C717 84 793 104 846 126 C877 139 892 153 876 165 C863 176 825 171 802 169 C839 213 872 279 875 329 C879 396 825 481 769 534 L772 388 C788 396 806 403 823 408 C773 389 728 368 707 345 C683 322 669 297 663 277 C678 335 721 370 752 386 C706 406 658 403 624 377 C594 352 574 309 567 251 C572 307 587 359 605 393 C585 419 551 409 519 388 C471 355 442 302 437 253 C424 313 397 392 368 410 C341 425 318 377 318 331 C318 296 327 257 338 226 C324 298 297 356 260 388 Z\"/>\n        <path fill=\"none\" stroke=\"#54545a\" stroke-width=\"9\" stroke-linecap=\"round\" d=\"M437 253 Q443 211 442 171 M604 395 Q550 358 521 288\"/>\n        <path fill=\"none\" stroke=\"#292929\" stroke-width=\"36\" stroke-linecap=\"round\" d=\"M327 460 Q382 457 437 458 M615 460 Q654 461 693 464\"/>\n        <g data-part=\"eyes\" fill=\"#282828\" stroke=\"none\">\n          <rect x=\"390\" y=\"501\" width=\"42\" height=\"64\" rx=\"20\"/>\n          <rect x=\"604\" y=\"500\" width=\"41\" height=\"64\" rx=\"20\"/>\n        </g>\n        <path fill=\"none\" stroke=\"#292929\" stroke-width=\"17\" stroke-linecap=\"round\" d=\"M518 534 L517 627 M469 691 Q513 714 553 694\"/>\n      </g>\n    </g>\n  </g>\n</svg>\n";
  const button = document.createElement('button');
  button.type = 'button';
  button.setAttribute('aria-label', 'Pop and dismiss companion');
  button.style.cssText = 'position:fixed;inset:0 auto auto 0;width:76px;height:104px;padding:0;border:0;border-radius:35%;background:none;cursor:pointer;z-index:90;touch-action:manipulation;-webkit-tap-highlight-color:transparent;';
  button.innerHTML = artwork;
  document.body.append(button);
  const svg = button.querySelector('svg');
  svg.setAttribute('aria-hidden', 'true');
  svg.style.cssText = 'display:block;width:100%;height:100%;overflow:visible;pointer-events:none;';
  const parts = Object.fromEntries([...svg.querySelectorAll('[data-part]')].map(part => [part.dataset.part, part]));
  let view3d;
  let yaw = .20;
  let hovered = false;
  let wave = 0;
  let waveStarted = 0;
  let idleStarted = 0;
  let traveled = 0;
  let arrived;
  let pantStarted;
  let puff;
  let dizzyStarted;
  let surpriseStarted;
  let pointerSample;
  let heading;
  let turns = [];
  const dizzyDuration = 2150;
  const emotion = { dizzy: 0, surprise: 0 };
  const longWalk = 335;
  const settleTime = .34;
  const breaths = [[.96, 1], [1.06, .57]];
  const breathingTime = settleTime + breaths.reduce((total, [duration]) => total + duration, 0);
  const recoveryTime = .82;
  let velocityX = 0;
  let velocityY = 0;
  let yawVelocity = 0;
  let weightShift = 0;
  let landingStarted;
  const landingTime = 125;
  const look = [0, 0, 0];
  // Alternate glances with pauses, then ease back to center.
  const idleBeats = [
    [0, 0, 0, 0], [.65, 0, 0, 0], [1.15, -.46, -.08, .055],
    [2.05, -.46, -.08, .055], [2.5, -.24, .11, .09],
    [3.08, -.24, .11, .09], [3.65, .48, -.12, -.055],
    [4.62, .48, -.12, -.055], [5.14, .18, -.22, -.06],
    [5.86, .18, -.22, -.06], [6.42, 0, 0, 0], [7.7, 0, 0, 0]
  ];

  function idleLook(time, active, dt) {
    if (!active) idleStarted = time;
    const elapsed = (Math.max(0, time - idleStarted) / 1000) % idleBeats.at(-1)[0];
    const next = idleBeats.findIndex(beat => beat[0] > elapsed);
    const from = idleBeats[next - 1];
    const to = idleBeats[next];
    const t = (elapsed - from[0]) / (to[0] - from[0]);
    const ease = t * t * (3 - 2 * t);
    for (let i = 0; i < look.length; i++) {
      const target = from[i + 1] + (to[i + 1] - from[i + 1]) * ease;
      look[i] += (target - look[i]) * Math.min(1, dt * 15);
    }
  }
  import('./figurine.js').then(({ createView }) => {
    const model = createView(76, 104);
    model.canvas.setAttribute('aria-hidden', 'true');
    button.append(model.canvas);
    svg.style.display = 'none';
    view3d = model;

  }).catch(error => console.warn('Using the illustrated companion fallback.', error));

  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const clamp = (value, max) => Math.max(0, Math.min(value, max));
  let x, y, targetX, targetY, cursorX, frame, previous, phase, stride, direction, popped;

  function pose(time, state) {
    const moving = state !== 'idle';
    const swing = Math.sin(phase) * stride;
    const bob = moving ? -Math.abs(Math.sin(phase)) * stride * .13 : Math.sin(time / 370) * 1.5;
    parts['leg-left'].setAttribute('transform', 'rotate(' + swing + ' 81 175)');
    parts['leg-right'].setAttribute('transform', 'rotate(' + -swing + ' 99 175)');
    parts.upper.setAttribute('transform', 'translate(0 ' + bob + ')');
    const greeting = wave * (120 + Math.sin((time - waveStarted) / 75) * 12);
    parts['arm-left'].setAttribute('transform', 'rotate(' + (-swing * 1.25 + greeting) + ' 73 134)');
    parts['arm-right'].setAttribute('transform', 'rotate(' + swing * 1.25 + ' 107 134)');
    const blink = time % 3750 > 3650;
    parts.eyes.setAttribute('transform', blink ? 'translate(0 480) scale(1 .1)' : '');
  }

  function tick(time) {
    if (popped) {
      const progress = (time - surpriseStarted) / 270;
      if (view3d) {
        yaw *= .72;
        emotion.dizzy = 0;
        emotion.surprise = Math.max(.01, progress);
        emotion.bracing = false;
        emotion.weightShift = 0;
        emotion.landing = undefined;
        view3d.draw(time, 0, 0, yaw, 0, 0, [0, 0, 0], 0, 0, emotion);
      }
      frame = requestAnimationFrame(tick);
      return;
    }
    const dt = Math.min(.04, (time - (previous ?? time)) / 1000);
    previous = time;
    const dx = clamp(targetX, innerWidth - 76) - x;
    const dy = clamp(targetY, innerHeight - 104) - y;
    const distance = Math.hypot(dx, dy);
    const dizzyTime = time - (dizzyStarted ?? -Infinity);
    const dizzy = !reduced.matches && dizzyTime < dizzyDuration;
    const canMove = !reduced.matches && !hovered && !dizzy;
    const cursorOffset = cursorX === undefined ? 0 : cursorX - (x + 38);
    if (Math.abs(cursorOffset) > 7) {
      const nextDirection = Math.sign(cursorOffset);
      if (canMove && distance >= 2 && nextDirection !== direction && Math.abs(velocityX) > 45) {
        landingStarted = time;
      }
      direction = nextDirection;
    }

    const state = canMove && distance >= 2 ? 'walk' : 'idle';
    if (state !== 'walk' || time - landingStarted > landingTime) landingStarted = undefined;
    let pace = 0;
    if (state === 'walk') {
      arrived = undefined;
      pantStarted = undefined;
      const speed = 155 * (.42 + .58 * clamp(distance / 28, 1));
      const steer = 1 - Math.exp(-dt * 24);
      velocityX += (dx / distance * speed - velocityX) * steer;
      velocityY += (dy / distance * speed - velocityY) * steer;
      const stepX = velocityX * dt;
      const stepY = velocityY * dt;
      const moveX = stepX * dx > 0 && Math.abs(stepX) > Math.abs(dx) ? dx : stepX;
      const moveY = stepY * dy > 0 && Math.abs(stepY) > Math.abs(dy) ? dy : stepY;
      x += moveX;
      y += moveY;
      pace = Math.hypot(velocityX, velocityY) / 155;
      // Keep the gait phase moving through the weight transfer on a reversal.
      phase += dt * (6.5 + 5.5 * pace);
      traveled += Math.hypot(moveX, moveY);
    } else if (!canMove) {
      velocityX = velocityY = 0;
      traveled = 0;
      arrived = pantStarted = undefined;
    } else {
      velocityX = velocityY = 0;
      arrived ??= time;
      if (time - arrived > 140 && traveled > 0) {
        if (traveled >= longWalk) pantStarted = time;
        traveled = 0;
      }
    }
    const pantTime = pantStarted === undefined ? Infinity : (time - pantStarted) / 1000;
    const resting = pantTime < breathingTime + recoveryTime;
    const bend = resting ? Math.min(1, pantTime / settleTime, (breathingTime + recoveryTime - pantTime) / recoveryTime) : 0;
    const fatigue = bend * bend * (3 - 2 * bend);
    let breath = 0;
    let remaining = Math.max(0, pantTime - settleTime);
    for (const [duration, strength] of breaths) {
      if (remaining < duration) {
        const inhaleTime = duration * .54;
        const inhale = Math.min(1, remaining / inhaleTime);
        const release = Math.max(0, (remaining - inhaleTime) / (duration - inhaleTime));
        const chestRise = .5 - .5 * Math.cos(inhale * Math.PI);
        const chestFall = .5 + .5 * Math.cos(release * Math.PI);
        breath = chestRise * chestFall * strength;
        break;
      }
      remaining -= duration;
    }
    const mood = dizzy ? 'dizzy' : hovered ? 'wave' : pantTime < breathingTime ? 'pant' : resting ? 'recover' : state;
    stride += ((state === 'walk' ? 11 + 7 * pace : 0) - stride) * Math.min(1, dt * 14);
    wave += ((hovered && !dizzy ? 1 : 0) - wave) * Math.min(1, dt * 12);
    x = clamp(x, innerWidth - 76);
    y = clamp(y, innerHeight - 104);
    button.style.transform = 'translate(' + x + 'px,' + y + 'px)';
    if (view3d) {
      idleLook(time, !reduced.matches && !hovered && !resting && !dizzy && state === 'idle', dt);
      const goal = hovered || dizzy || resting ? 0 : state === 'idle' ? direction * .20 : direction * 1.12;
      // Damped rotation keeps angular speed continuous when the goal changes.
      const rate = state === 'walk' ? 23 : 15;
      const offset = yaw - goal;
      const momentum = yawVelocity + rate * offset;
      const decay = Math.exp(-rate * dt);
      yaw = goal + (offset + momentum * dt) * decay;
      yawVelocity = (yawVelocity - rate * momentum * dt) * decay;
      const lean = state === 'walk' ? Math.max(-1, Math.min(1, yawVelocity / 16)) : 0;
      weightShift += (lean - weightShift) * (1 - Math.exp(-dt * 12));
      emotion.dizzy = dizzy ? Math.min(1, (dizzyDuration - dizzyTime) / 340) : 0;
      emotion.surprise = 0;
      emotion.bracing = resting;
      emotion.weightShift = weightShift;
      emotion.landing = landingStarted;
      emotion.landingProgress = landingStarted === undefined ? 0 : (time - landingStarted) / landingTime;
      emotion.screenX = x;
      emotion.screenY = y;
      view3d.draw(reduced.matches ? 0 : time, phase, stride * Math.PI / 180, yaw, wave,
        reduced.matches ? 0 : (time - waveStarted) / 1000, look, breath, fatigue, emotion);
    } else {
      svg.style.transform = 'scaleX(' + direction + ')';
      if (!reduced.matches) pose(time, state);
      else pose(0, 'idle');
    }
    button.dataset.state = mood;
    frame = requestAnimationFrame(tick);
  }

  function trackCircles(px, py, time) {
    if (reduced.matches || time - (dizzyStarted ?? -Infinity) < dizzyDuration) return;
    if (!pointerSample || time - pointerSample.time > 950) {
      pointerSample = { x: px, y: py, time };
      heading = undefined;
      turns = [];
      return;
    }
    const dx = px - pointerSample.x;
    const dy = py - pointerSample.y;
    if (Math.hypot(dx, dy) < 18) return;
    pointerSample = { x: px, y: py, time };
    const nextHeading = Math.atan2(dy, dx);
    if (heading !== undefined) {
      const delta = Math.atan2(Math.sin(nextHeading - heading), Math.cos(nextHeading - heading));
      // A reversal is a change of mind, not another turn around the loop.
      if (Math.abs(delta) > 2.15) turns = [];
      else turns.push({ time, delta });
      while (turns.length && time - turns[0].time > 16000) turns.shift();
      const rotation = turns.reduce((sum, turn) => sum + turn.delta, 0);
      if (Math.abs(rotation) >= Math.PI * 3 && traveled >= 185) {
        dizzyStarted = time;
        turns = [];
        pointerSample = heading = undefined;
        return;
      }
    }
    heading = nextHeading;
  }

  function follow(event) {
    if (popped || event.target.closest?.('button, a, input, textarea, select, [contenteditable]')) return;
    cursorX = event.clientX;
    if (event.pointerType === 'mouse') trackCircles(event.clientX, event.clientY, performance.now());
    // Leave space around the pointer so the companion can be approached and clicked.
    const onRight = cursorX >= x + 38;
    const offset = onRight ? -101 : 25;
    const followX = cursorX + offset;
    targetX = onRight ? Math.max(x, followX) : Math.min(x, followX);
    targetY = event.clientY + (event.clientY < innerHeight * .66 ? 16 : -120);
  }

  function reset() {
    cancelAnimationFrame(frame);
    button.getAnimations().forEach(animation => animation.cancel());
    popped = hovered = false;
    wave = traveled = 0;
    arrived = pantStarted = dizzyStarted = surpriseStarted = undefined;
    pointerSample = heading = undefined;
    velocityX = velocityY = yawVelocity = weightShift = 0;
    landingStarted = undefined;
    turns = [];
    puff?.remove();
    button.hidden = false;
    button.style.pointerEvents = '';
    x = targetX = clamp(innerWidth - 115, innerWidth - 76);
    y = targetY = clamp(innerHeight - 144, innerHeight - 104);
    previous = undefined;
    phase = stride = 0;
    direction = 1;
    cursorX = undefined;
    yaw = .20;
    idleStarted = performance.now();
    look.fill(0);
    tick(idleStarted);
  }

  button.addEventListener('pointerenter', event => {
    if (event.pointerType !== 'mouse') return;
    hovered = true;
    waveStarted = performance.now();
    targetX = x;
    targetY = y;
  });
  button.addEventListener('pointerleave', () => { hovered = false; });
  button.addEventListener('click', async () => {
    if (popped) return;
    popped = true;
    cancelAnimationFrame(frame);
    button.style.pointerEvents = 'none';
    if (!reduced.matches) {
      button.dataset.state = 'surprised';
      surpriseStarted = performance.now();
      frame = requestAnimationFrame(tick);
      const reaction = button.animate([
        { translate: '0 0' }, { translate: '0 -5px', offset: .34 }, { translate: '0 0' }
      ], { duration: 270, easing: 'ease-out' });
      try { await reaction.finished; }
      catch { return; } // Reset canceled the reaction.
      cancelAnimationFrame(frame);
      button.dataset.state = 'pop';
      const base = button.style.transform;
      const animation = button.animate([
        { transform: base + ' scale(1)', opacity: 1 },
        { transform: base + ' translateY(5px) scale(1.15,.79)', opacity: 1, offset: .26 },
        { transform: base + ' translateY(-5px) scale(.88,1.15)', opacity: 1, offset: .43 },
        { transform: base + ' translateY(-9px) scale(.25)', opacity: 0, offset: .76 },
        { transform: base + ' scale(.1)', opacity: 0 }
      ], { duration: 430, easing: 'ease-out', fill: 'forwards' });

      puff = document.createElement('span');
      puff.setAttribute('aria-hidden', 'true');
      puff.style.cssText = 'position:fixed;pointer-events:none;z-index:91;left:' + (x + 38) + 'px;top:' + (y + 53) + 'px';
      document.body.append(puff);
      for (let i = 0; i < 7; i++) {
        const dot = document.createElement('span');
        dot.style.cssText = 'position:absolute;left:-3px;top:-3px;width:6px;height:6px;border-radius:50%;background:#f4efe5;box-shadow:0 0 0 1px #544f3a44';
        puff.append(dot);
        const angle = i * Math.PI * 2 / 7;
        const radius = 23 + i % 3 * 6;
        dot.animate([
          { opacity: 0, transform: 'scale(.2)' },
          { opacity: 1, offset: .19 },
          { opacity: 0, transform: 'translate(' + Math.cos(angle) * radius + 'px,' + Math.sin(angle) * radius + 'px) scale(.5)' }
        ], { duration: 285, delay: 145, fill: 'both', easing: 'ease-out' });
      }
      try { await animation.finished; }
      catch { return; } // Reset canceled the pop.
    }
    puff?.remove();
    button.hidden = true;
  });
  window.addEventListener('pointermove', follow, { passive: true });
  window.addEventListener('pointerdown', event => {
    if (event.pointerType === 'touch') follow(event);
  }, { passive: true });
  document.addEventListener('companion:reset', reset);
  reset();
})();
